import icontract
from typing import List


@icontract.ensure(lambda result: result >= 0)
@icontract.ensure(lambda a, result: result <= len(a))
@icontract.ensure(lambda a, e, result: result == len(a) or a[result] == e)
@icontract.ensure(lambda a, e, result: all(a[i] != e for i in range(result)))
def LinearSearch(a: List[int], e: int) -> int:
    i = 0
    while i < len(a) and a[i] != e:
        i += 1
    return i
